const plan = [];
const sources = [
  { domain: 'books.toscrape.com', wait_ms: 2000, pages: 5, url: n => `https://books.toscrape.com/catalogue/page-${n}.html` },
  { domain: 'quotes.toscrape.com', wait_ms: 2000, pages: 5, url: n => `https://quotes.toscrape.com/page/${n}/` },
  { domain: 'scrapingcourse.com', wait_ms: 1000, pages: 5, url: n => `https://scrapingcourse.com/ajax/products?offset=${(n - 1) * 10}` }
];
for (const s of sources) {
  for (let p = 1; p <= s.pages; p++) {
    plan.push({ json: { domain: s.domain, url: s.url(p), wait_ms: s.wait_ms } });
  }
}
return plan;

const plan = $('План сбора (15 страниц)').all();
const out = [];
for (const item of $input.all()) {
  const idx = (item.pairedItem && typeof item.pairedItem.item === 'number') ? item.pairedItem.item : out.length;
  const src = (plan[idx] && plan[idx].json) ? plan[idx].json : {};
  const body = String(item.json.data || item.json.body || '');
  const count = (body.match(/class="[^"]*\b(product_pod|quote|product-item)\b/g) || []).length;
  out.push({ json: {
    domain: src.domain || null,
    url: src.url || null,
    status: (item.json.statusCode !== undefined ? item.json.statusCode : 200),
    items: count,
    collected_at: new Date().toISOString()
  } });
}
return out;

const rows = $input.all().map(i => i.json).filter(r => r && r.url);
const text = rows.map(r => JSON.stringify(r)).join('\n') + '\n';
return [{ json: {
  written: rows.length,
  records: rows.reduce((s, r) => s + (r.items || 0), 0),
  pages: rows.length,
  domains: [...new Set(rows.map(r => r.domain))],
  file: 'nocode_result.jsonl'
}, binary: { data: { data: Buffer.from(text, 'utf8').toString('base64'), mimeType: 'application/x-ndjson', fileName: 'nocode_result.jsonl' } } }];

const s = $json;
const text = JSON.stringify({ event: 'insufficient_records', records: s.records, pages: s.pages, domains: s.domains, at: new Date().toISOString() }) + '\n';
return [{ json: { written: 1, file: 'nocode_alerts.jsonl' }, binary: { data: { data: Buffer.from(text, 'utf8').toString('base64'), mimeType: 'application/x-ndjson', fileName: 'nocode_alerts.jsonl' } } }];

const rows = $input.all().map(i => i.json).filter(r => r && r.status && r.status !== 200);
const text = rows.map(r => JSON.stringify({ event: 'non_200_status', domain: r.domain, url: r.url, status: r.status, at: new Date().toISOString() })).join('\n');
if (!rows.length) { return []; }
return [{ json: { written: rows.length, file: 'nocode_alerts.jsonl' }, binary: { data: { data: Buffer.from(text + '\n', 'utf8').toString('base64'), mimeType: 'application/x-ndjson', fileName: 'nocode_alerts.jsonl' } } }];
